    end: (chunk) => { chunks.push(chunk); },
    write: (chunk) => { chunks.push(chunk); },
    on: () => {},
    _code: () => code,
    _body: () => chunks.map((c) => (typeof c === "string" ? c : String(c))).join(""),
  };
}

