  mkdirSync(authLocal, { recursive: true });
  const restore = isolateCredEnv(authDir);
  try {
    writeFileSync(join(authLocal, "auth.json"), JSON.stringify({
      "opencode-go": { type: "api", key: "sk-auth-json" },
