  assert.equal(data.monthly.limit, 60, "缺失窗口补默认限额");
}
{
  const data = await fetchOpenCodeGoV2(
    baseCtx({ apiEndpoint: "" }),
    makeFetch(200, okBody),
  );
  assert.equal(data.rolling.percent, 11, "空 apiEndpoint 回落默认地址仍成功");
}

